class Machine {
  constructor(stock) { this.stock = stock; this.balance = 0; this.state = 'IDLE'; }
  insert(c) {
    if (this.state === 'SOLD_OUT') return 'refund ' + c;
    this.balance += c; this.state = 'HAS_MONEY'; return 'bal ' + this.balance;
  }
  select(price) {
    if (this.state !== 'HAS_MONEY') return 'insert money';
    if (this.balance < price) return 'need ' + (price - this.balance);
    const change = this.balance - price;
    this.balance = 0; this.stock--;
    this.state = this.stock === 0 ? 'SOLD_OUT' : 'IDLE';
    return 'item, change ' + change;
  }
}
const m = new Machine(1);
console.log([m.select(15), m.insert(10), m.select(15), m.insert(10), m.select(15), m.insert(5)].join(' | '));

