const DAY = 24 * 60 * 60 * 1000;
function fine(due, returned, perDay, cap) {
  const late = Math.max(0, Math.ceil((returned - due) / DAY));
  return Math.min(late * perDay, cap);
}
const due = Date.UTC(2026, 0, 10);
