function makeChange(amount, inventory) {
  const coins = Object.keys(inventory).map(Number).sort((a, b) => b - a);
  const used = {};
  for (const c of coins) {
    const n = Math.min(Math.floor(amount / c), inventory[c]);
    if (n > 0) { used[c] = n; amount -= n * c; }
  }
  return amount === 0 ? JSON.stringify(used) : 'cannot';
}
console.log(makeChange(30, { 10: 1, 5: 3, 1: 10 }));
console.log(makeChange(8, { 5: 1, 4: 2 }));
